  text-align: center;
  letter-spacing: 0.3em;
  background: var(--mat-sys-surface-container-highest);
  color: var(--mat-sys-on-surface);
}

.seat-map {
  width: $map-width;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.seat-row {
  height: $seat;
  display: flex;
  align-items: center;
  gap: $gap;
}

.row-label {
  width: $label;
  flex: none;
  text-align: center;
  font-size: 12px;
  color: var(--mat-sys-on-surface-variant);
}

.entrance {
  width: $block-left;
  flex: none;
}

.aisle {
  width: $aisle;
  flex: none;
}

.block {
  display: flex;
  gap: $gap;
  flex: none;
}

.seat,
.couch {
  flex: none;
  height: $seat;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 6px;
  color: #fff;
  font: inherit;
  font-size: 12px;
  line-height: 1;

  // Background colours by state. There are no hover or focus rules, so the colour never changes on hover or focus.
