// Background colour of each state, shared by the seats and the legend swatches.
$state-colors: (
  'available': #2e7d32,
  'selected': #f9a825,
  'unavailable': #c62828,
  'accessible': #1565c0,
);

.seat,
.couch {
  flex: none;
  height: $seat;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 6px;
  color: #fff;
  font: inherit;
  font-size: 12px;
  line-height: 1;

  // There are no hover or focus rules, so the background colour never changes on hover or focus.
  &[data-state='selected'] {
    color: #212121;
  }
}

@each $state, $color in $state-colors {
  .seat[data-state='#{$state}'],
  .couch[data-state='#{$state}'],
  .legend-item[data-state='#{$state}'] .swatch {
    background-color: $color;
  }
}

.seat {
  width: $seat;
}

.couch {
  width: $aisle;
  font-weight: 500;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 24px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
}

.swatch {
  width: 16px;
  height: 16px;
  border-radius: 4px;
}

.selected-seats {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  margin-top: 8px;

  p {
    margin: 0;
  }
}

.selected-seats-count {
  font-weight: 500;
}

.actions {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 8px;
}

